Dim TmpName As String Dim TmpMask As String If Obj_Type_Nr < 1 Then Obj_Type_Nr = 1 ElseIf Obj_Type_Nr > 3 Then Obj_Type_Nr = 3 End If SchemeNr = "BRK" + CStr(Obj_Type_Nr) TopicID = "ObjectRules_" + SchemeNr Delimiter = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_DELIMITER")) Is_NARY = CBool(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_USE_SINGLE_NARY")) 'чтобы не задействовать лишние переменные If Is_NARY Then //это один NARY pv_ON = BIN(KKS + Delimiter + CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_ON"))) mask_ON = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON")) mask_OFF = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF")) mask_NOT_ON = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_NOT_ON")) mask_NOT_OFF = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_NOT_OFF")) mask_START = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_START")) mask_STOP = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_STOP")) mask_ON_MISMATCH = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON_MISMATCH")) mask_OFF_MISMATCH = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF_MISMATCH")) mask_ON_OVERTIME = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON_OVERTIME")) mask_OFF_OVERTIME = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF_OVERTIME")) mask_FAIL = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_FAIL")) mask_FAIL_BLINK = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_FAIL_BLINK")) mask_INVALID = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_INVALID")) mask_UNDEFINED = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_UNDEFINED")) mask_TEST = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_TEST")) mask_REPAIR = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_REPAIR")) mask_SELECTED = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_SELECTED")) Else TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_ON")) If TmpName != "NONE" Then pv_ON = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_OFF")) If TmpName != "NONE" Then pv_OFF = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_NOT_ON")) If TmpName != "NONE" Then pv_NOT_ON = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_NOT_OFF")) If TmpName != "NONE" Then pv_NOT_OFF = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_START")) If TmpName != "NONE" Then pv_START = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_STOP")) If TmpName != "NONE" Then pv_STOP = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_ON_MISMATCH")) If TmpName != "NONE" Then pv_ON_MISMATCH = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_OFF_MISMATCH")) If TmpName != "NONE" Then pv_OFF_MISMATCH = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_ON_OVERTIME")) If TmpName != "NONE" Then pv_ON_OVERTIME = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_OFF_OVERTIME")) If TmpName != "NONE" Then pv_OFF_OVERTIME = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_FAIL")) If TmpName != "NONE" Then pv_FAIL = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_FAIL_BLINK")) If TmpName != "NONE" Then pv_FAIL_BLINK = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_INVALID")) If TmpName != "NONE" Then pv_INVALID = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_UNDEFINED")) If TmpName != "NONE" Then pv_UNDEFINED = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_TEST")) If TmpName != "NONE" Then pv_TEST = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_REPAIR")) If TmpName != "NONE" Then pv_REPAIR = BIN(KKS + Delimiter + TmpName) End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_SELECTED")) If TmpName != "NONE" Then pv_SELECTED = BIN(KKS + Delimiter + TmpName) End If If CBool(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_APPLY_MASK")) Then If pv_ON != Nothing Then mask_ON = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON")) End If If pv_OFF != Nothing Then mask_OFF = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF")) End If If pv_NOT_ON != Nothing Then mask_NOT_ON = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_NOT_ON")) End If If pv_NOT_OFF != Nothing Then mask_NOT_OFF = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_NOT_OFF")) End If If pv_START != Nothing Then mask_START = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_START")) End If If pv_STOP != Nothing Then mask_STOP = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_STOP")) End If If pv_ON_MISMATCH != Nothing Then mask_ON_MISMATCH = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON_MISMATCH")) End If If pv_OFF_MISMATCH != Nothing Then mask_OFF_MISMATCH = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF_MISMATCH")) End If If pv_ON_OVERTIME != Nothing Then mask_ON_OVERTIME = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_ON_OVERTIME")) End If If pv_OFF_OVERTIME != Nothing Then mask_OFF_OVERTIME = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_OFF_OVERTIME")) End If If pv_FAIL != Nothing Then mask_FAIL = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_FAIL")) End If If pv_FAIL_BLINK != Nothing Then mask_FAIL_BLINK = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_FAIL_BLINK")) End If If pv_INVALID != Nothing Then mask_INVALID = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_INVALID")) End If If pv_UNDEFINED != Nothing Then mask_UNDEFINED = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_UNDEFINED")) End If If pv_TEST != Nothing Then mask_TEST = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_TEST")) End If If pv_REPAIR != Nothing Then mask_REPAIR = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_REPAIR")) End If If pv_SELECTED != Nothing Then mask_SELECTED = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_SELECTED")) End If End If End If //сигналы тележки кодируются отдельно от основного сигнала If HasTray Then TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_PVMASK_TR_POS_TEST")) If TmpName != "NONE" Then If Left(TmpName, 1) == "." Then 'если первый символ = точка, значит задана маска с точками TmpMask = PRJSPEC.BuildFinalMask(KKS, TmpName) Else 'иначе - маской является расширение после разделителя TmpMask = KKS + Delimiter + TmpName End If pv_TR_TEST = BIN(TmpMask) If pv_TR_TEST != Nothing Then mask_TR_TEST = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_TR_POS_TEST")) End If End If TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_PVMASK_TR_POS_REPAIR")) If TmpName != "NONE" Then If Left(TmpName, 1) == "." Then 'если первый символ = точка, значит задана маска с точками TmpMask = PRJSPEC.BuildFinalMask(KKS, TmpName) Else 'иначе - маской является расширение после разделителя TmpMask = KKS + Delimiter + TmpName End If pv_TR_OUT = BIN(TmpMask) If pv_TR_OUT != Nothing Then mask_TR_OUT = CUInt(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_MASK_TR_POS_REPAIR")) End If End If End If
//изначально всё пусть будет скрыто ON.visibility = "hidden" OFF.visibility = "hidden" NOT_ON.visibility = "hidden" NOT_OFF.visibility = "hidden" START.visibility = "hidden" STOP.visibility = "hidden" ON_MISMATCH.visibility = "hidden" OFF_MISMATCH.visibility = "hidden" ON_OVERTIME.visibility = "hidden" OFF_OVERTIME.visibility = "hidden" FAIL.visibility = "hidden" FAIL_BLINK.visibility = "hidden" INVALID.visibility = "hidden" UNDEFINED.visibility = "hidden" TEST.visibility = "hidden" REPAIR.visibility = "hidden" SELECTED.visibility = "hidden" TR_TEST.visibility = "hidden" TR_OUT.visibility = "hidden" TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_SIGNAL_COMMAND")) If TmpName != "NONE" Then pv_OU = BIN(KKS + Delimiter + TmpName) End If If (pv_OU == nothing) Then No_OU = True ElseIf (pv_OU.PVCategories != 2) Then No_OU = True Else No_OU = False End If If No_OU Then NO_OU.title = "Переменная " + KKS + Delimiter + TmpName + " не найдена или ее тип не Out" End If
TmpName = CStr(RTAPLS.GetConfigurationParameter(True, TopicID, SchemeNr + "_AUX_SIGNAL_MASK")) If Left(TmpName, 1) == "." Then 'если первый символ = точка, значит задана маска с точками Mask = PRJSPEC.BuildFinalMask(KKS, TmpName) Else 'иначе - маской является расширение после разделителя Mask = KKS + Delimiter + TmpName End If Dim selBINs(100) As Int Dim selANAs(100) As Int Dim actualANAs As Int Dim actualBINs As Int More_signals = PRJSPEC.GET_Selection(Mask, actualANAs, actualBINs, selANAs, selBINs)
